pub fn set_protection(app: &App, view: &ProtectionPageView) {
    let toggles: Vec<ToggleRow> = view
        .toggles
        .iter()
        .map(|t| ToggleRow {
            key: t.key.clone().into(),
            label: t.label.clone().into(),
            hint: t.hint.clone().into(),
            on: t.on,
            available: t.available,
        })
        .collect();
    app.set_prot_toggles(ModelRc::from(Rc::new(VecModel::from(toggles))));
    let folders: Vec<SharedString> = view.folders.iter().map(|f| f.clone().into()).collect();
    app.set_prot_folders(ModelRc::from(Rc::new(VecModel::from(folders))));
    let halted: Vec<QuarRow> = view
        .halted
        .iter()
        .map(|h| QuarRow {
            id: h.id.clone().into(),
            title: h.title.clone().into(),
            detail: h.detail.clone().into(),
        })
        .collect();
    app.set_prot_halted(ModelRc::from(Rc::new(VecModel::from(halted))));
    app.set_prot_notes(ModelRc::from(Rc::new(VecModel::from(pairs(&view.notes)))));
    app.set_show_cfa(view.show_cfa);
}

pub fn set_protection_system(app: &App, rows: &[(String, String)]) {
    app.set_prot_system_rows(ModelRc::from(Rc::new(VecModel::from(pairs(rows)))));
}

fn pairs(rows: &[(String, String)]) -> Vec<DeepRow> {
    rows.iter()
        .map(|(title, detail)| DeepRow {
            title: title.clone().into(),
            detail: detail.clone().into(),
        })
        .collect()
}

pub fn set_network(app: &App, view: &NetworkPageView) {
    app.set_net_summary(view.summary.clone().into());
    app.set_net_scanning(view.scanning);
    app.set_net_change_rows(ModelRc::from(Rc::new(VecModel::from(pairs(&view.changes)))));
    let devices: Vec<NetDevRow> = view
        .devices
        .iter()
        .map(|d| NetDevRow {
            key: d.key.clone().into(),
            ip: d.ip.clone().into(),
            title: d.title.clone().into(),
            detail: d.detail.clone().into(),
            badge: d.badge.clone().into(),
            trusted: d.trusted,
            can_check: d.can_check,
        })
        .collect();
    app.set_net_devices(ModelRc::from(Rc::new(VecModel::from(devices))));
    let findings: Vec<FindingRow> = view
        .findings
        .iter()
        .map(|(title, detail, severity)| FindingRow {
            title: title.clone().into(),
            detail: detail.clone().into(),
            severity: severity.clone().into(),
        })
        .collect();
    app.set_net_finding_rows(ModelRc::from(Rc::new(VecModel::from(findings))));
}
